import numpy as np, warnings
warnings.filterwarnings('ignore')
import pybamm

x = pybamm.SpatialVariable('x', domain='domain', coord_sys='cartesian')
u = pybamm.Variable('u', domain='domain')

for direction, side, op, bv in [('upwind','left',pybamm.upwind,0.0), ('downwind','right',pybamm.downwind,0.25)]:
    bcs = {u: {side: (pybamm.Scalar(bv), 'Dirichlet')}}
    model = pybamm.BaseModel()
    model.rhs = {u: -u}
    model.initial_conditions = {u: pybamm.Scalar(0)}
    model.boundary_conditions = bcs
    model.variables = {'edge_state': op(u)}
    geometry = {'domain': {x: {'min': pybamm.Scalar(0), 'max': pybamm.Scalar(1)}}}
    if direction=='upwind':
        profile = np.array([1.,2.,3.,4.,5.])
