    disc = pybamm.Discretisation(mesh, {'domain': pybamm.FiniteVolume()})
    processed = disc.process_model(model, inplace=False)
    es = processed.variables['edge_state']
    print(direction, 'expression:', es)
    edges = np.asarray(es.evaluate(y=profile[:,None])).reshape(-1)
    print('edges:', edges)
